import{_ as n,l as o,o as e,c as l,v as r,p as c,x as t,d as s,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Manacher","description":"","frontmatter":{"title":"Manacher","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/manacher.md","filePath":"cs/manacher.md","lastUpdated":1789023840000}'),p={name:"cs/manacher.md"};function m(_,a,u,E,f,P){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="manacher" tabindex="-1">Manacher <a class="header-anchor" href="#manacher" aria-label="Permalink to &quot;Manacher&quot;">​</a></h1><div class="epigraph"><p>回文半径数组在已覆盖的对称窗口内复制，再尝试延长，线性求出全部最长回文半径。</p><footer>—— 据 Manacher, A New Linear-Time On-Line Algorithm for Finding the Longest Palindromic Substring, 1975 整理</footer></div><p>上一课<a href="/cs/z-function">Z 函数</a>用 LCP 窗口。回文是中心对称，不是与前缀 LCP。缺口是 Manacher：奇偶中心用插入分隔符统一，半径 \\(p[i]\\)，\\(i\\) 落在中心 \\(c\\) 的窗口内则对称点有下界。不重写 Z-box 定义。后课最小表示法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最长回文子串朴素 \\(O(n^2)\\) 扩中心。Manacher：串 <code>^#a#b#...#$</code> 使全奇。维护最右 \\(r\\) 与中心 \\(c\\)。\\(i\\le r\\) 时 \\(p[i]\\ge\\min(p[2c-i], r-i)\\)，再扩。\\(r\\) 单调，\\(O(n)\\)。</p><p>缺口是对称复制，不是哈希判回文（期望线性）。</p><h3 id="子串不是子序列" tabindex="-1">子串不是子序列 <a class="header-anchor" href="#子串不是子序列" aria-label="Permalink to &quot;子串不是子序列&quot;">​</a></h3><p>回文子序列是另一 DP。本课连续子串。不要用 LCS 与反串当本课主算法——那是 \\(O(n^2)\\)。</p><p><span class="marginnote"> Manacher 1975。后课最小表示是旋转，不是回文。回文树（eertree）点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>变换串。扫 \\(i\\)，按盒更新 \\(p[i]\\)，尝试扩，更新 \\(c,r\\)。原串下标换算。最长取 \\(\\max p\\)。</p>',11)),(e(),c(d,null,{default:t(()=>[h(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%8F%92%20%23%20%E7%BB%9F%E4%B8%80%E5%A5%87%E5%BF%83%22%5D%20--%5Cgt%20%20C%5B%22%E4%B8%AD%E5%BF%83%20c%2C%20%E5%8F%B3%E7%95%8C%20r%22%5D%0A%20%20C%20--%5Cgt%20%20P%5B%22%E5%8D%8A%E5%BE%84%20p%5Bi%5D%22%5D%0A%20%20P%20--%5Cgt%20%20PAL%5B%22%E5%85%A8%E9%83%A8%E5%9B%9E%E6%96%87%E5%AD%90%E4%B8%B2%E5%8D%8A%E5%BE%84%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>计数不同回文子串要再处理。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>回文关于 \\(c\\) 对称，窗口内的半径被对称点限制，超出部分才比较字符。与 Z：都是窗口均摊。与 KMP 无直接公式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写回文树。不写二维回文。后课默认：最长回文子串线性 Manacher。下一课循环串最小表示。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>半径数组 + 对称窗口 = \\(O(n)\\)。</li><li>连续回文子串，不是子序列。</li><li>分隔符统一奇偶中心。</li><li>出处：Manacher, 1975。</li></ul>',7))])}const b=n(p,[["render",m]]);export{B as __pageData,b as default};
